        if hires == 0:
            mismatches.append(f\"{req}: Status=Filled, Headcount={hc}, Actual Hires={hires} (Zero Hires)\")
        else:
            mismatches.append(f\"{req}: Status=Filled, Headcount={hc}, Actual Hires={hires} (Over-hired)\")
